1	//! Access to `argv`, matching the C++ program's view of it.
2	
3	/// The process arguments, including `argv[0]`, so that indices line up with the
4	/// C++ `argv` and `args().len()` equals `argc`.
5	///
6	/// This is [`std::env::args`] with one deliberate difference: `std::env::args`
7	/// panics if any argument is not valid UTF-8, whereas C++ hands `main` raw bytes
8	/// and never fails. Going through [`std::env::args_os`] and replacing invalid
9	/// bytes keeps the C++ behaviour — such bytes are not digits, so the parse
10	/// outcome is the same one `std::stoi` would reach.
11	pub fn args() -> Vec<String> {
12	    std::env::args_os()
13	        .map(|arg| arg.to_string_lossy().into_owned())
14	        .collect()
15	}
16	
17	/// The `index`-th argument (`argv[index]`), or `None` when `argc <= index`.
18	pub fn arg(index: usize) -> Option<String> {
19	    args().into_iter().nth(index)
20	}
21	
22	#[cfg(test)]
23	mod tests {
24	    use super::*;
25	
26	    #[test]
27	    fn argv_zero_is_always_present() {
28	        // The test harness is itself a process, so `argv[0]` exists.
29	        assert!(!args().is_empty());
30	        assert!(arg(0).is_some());
31	        assert_eq!(arg(usize::MAX), None);
32	    }
33	}
